export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "06:45。朝倉家附近。二十四小時便利店。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在靠窗的位置。面前放著一杯沒打開的礦泉水。手機螢幕朝下扣在桌上。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "門推開。日下部悟走進來。深色西裝。領帶鬆了。眼下有青黑色。清晨勤務的疲態。他掃了一眼店內。看見澪。走過來。拉開對面的椅子坐下。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯說吧。五分鐘能驗證什麼。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "先回答我一個問題。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部的眼睛窄了一下。沒有說話。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "昨晚，有沒有人叫你記住一句和案件完全無關的話？", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部看著她。表情沒有變。但他的手指在桌面上停了一秒。像是在找什麼。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯沒有。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "想一下。不是案件的話。跟悠真無關。跟 TOKYO 無關。跟你正在辦的任何東西都無關。一句話。或者——一個感覺。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部沒有立刻回答。他靠回椅背。視線移到窗外。灰白的清晨光。便利店的招牌。對面公寓的牆。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯黃色。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "什麼？", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "不知道。就是——黃色。還有⋯⋯嘴裡有金屬味。像舔到鐵鏽。然後是海邊。不是看見海。是聞到。鹹的。濕的。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他停了一下。眉心皺起來。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "還有一個⋯⋯排列。什麼東西排在一起。但少了一排。缺了一個位置。說不清楚。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯黃色。金屬味。海邊。缺少的一排。碎片。不是完整句子。是身體殘留。方向感。氣味。視覺。這不能作證。但他有東西。那個白光——在他身上留了碎片。不能確定。但方向對了。現在——半句提示。先給跟案子無關的。再問案子。順序不能反。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪把礦泉水推到一邊。雙手放在桌上。看著日下部。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "那台黃色販賣機⋯⋯", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部的身體僵了一瞬。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他的嘴張開。聲音從喉嚨裡出來。不是思考過的聲音。是被什麼東西推出來的。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯沒有第四排。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他停住了。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "便利店裡很安靜。冷櫃的馬達在嗡。窗外有一輛車經過。然後又安靜了。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部看著澪。眼睛裡有東西在動。不是憤怒。不是理解。是一種——不確定自己在哪裡的表情。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯我為什麼會說這個。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "因為你見過那台販賣機。但不是這一輪見過的。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部沒有接話。他的手指在桌面上敲了一下。停住。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯他接出來了。「沒有第四排。」完整。不是自己想起來的。是半句提示後完成的。但——他完成了。這一次他不該知道這句話。現在——證明這句話這一次不存在。不能讓太多東西干擾判斷。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪把手機翻過來。打開瀏覽器。找到一個公開活動日程頁面。轉給日下部看。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "這台黃色販賣機。屬於週末灣岸活動的臨時設備。你看這個公開活動日程——安裝日是這個週六。今天是星期一。它還沒被裝上去。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部低頭看螢幕。看了五秒。抬頭。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯我沒見過這台販賣機。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "對。你沒見過。這一次它還不存在。你在電話裡也只聽到我說「那台黃色販賣機」——我沒有說下半句。是你自己接出「沒有第四排」的。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部的下巴收緊了。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "這句話跟朝倉父親舊案無關。跟 TOKYO 無關。跟千田無關。跟悠真無關。跟你手上的任何警務資料無關。它只是一台販賣機。一台這一次還沒安裝的販賣機。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部沒有說話。他把視線移回窗外。停了很久。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯測試完成。他完成了一句這一次不該知道的話。這比問 TOKYO 更可靠。因為這句話跟案件完全無關。沒有人有理由提前告訴他。沒有檔案可以查到。沒有公開資料可以推導。他只能從某個不屬於這一次的來源拿到它。現在——問案子。先給無關提示。再問案子。對。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪把手機收回來。看著日下部。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "再一個問題。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部的視線回到她身上。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "TOKYO 是不是地域欄？", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部的表情裂開了。不是一種情緒。是好幾種東西同時出現又互相擠壓。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他的嘴動了一下。像要說什麼。又停住。他的右手無意識地按了一下肋下。然後他自己愣住了。把手放下。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯不是。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他說完以後又停了三秒。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯我不知道我為什麼這麼肯定。你父親的舊筆記裡有 TOKYO 這個詞。我看過。但——", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他沒有說完。他的視線飄了一下。像在看什麼不在這裡的東西。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯混合反應。他想起父親舊筆記。本能回答「不是」。但他同時在看別的東西——舊案記憶跟那個白光混在一起。他無法區分來源。是父親舊案。還是那個白光。他自己也不知道。這比剛才複雜。因為問案子有太多可能的干擾來源。不能單獨作證。但——他說了「不是」。方向一致。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部把手放在桌上。手指攤開。又收攏。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯你想說什麼。直接說。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我接下來給你看的東西。全部是這一次已經存在的普通資料。不靠你剛才說的任何一句話。不靠我的記憶。不靠我說的循環。每一項你都可以自己查證。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把手機轉過來。一項一項放給他看。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第一項。悠真第二階段預約頁。這是家庭共享雲端的備份。家中平板同步的。時間早於悠真失蹤。不需要悠真的實體手機。頁面最下方——G07／12。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部低頭看。手指在螢幕上放大。看了很久。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯G07／12。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第二項。小鏡子背面。悠真的私人物品。有刻痕。今天早上拍的。只能看見部分筆畫。讀不出完整代碼。但這部分跟 G07／12 對得上。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻到鏡背照片。日下部看了一眼。眉心收緊。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第三項。筑波設施公開頁面。這裡有設施名稱、地址。還有災害反應、睡眠研究、警報相關業務。園區裝卸預約時段。合作物流公司的固定路線。職員接駁到站時間。清晨值班和搬送的職缺資訊。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她滑過幾張截圖。日下部沒有打斷。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第四項。悠真遊戲帳號裡的座標。這一次還在。落在同一個研究區。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她打開遊戲帳號頁面。座標截圖。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第五項。時間。沒有任何一份公開頁直接寫「受試者轉送」。但把裝卸預約、物流路線、職員接駁、清晨搬送班——拼在一起看。08:45 到 09:15。後方服務口那個時段最可能。這只是推測。不是公開寫的。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部的手指在桌面上敲了兩下。停住。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第六項。千田浩介。舊防災研討會頁面。TKS 公共警報同步的講題。跟灣岸系統的公開職務連結。全部公開。全部這一次就存在。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把手機放下。看著日下部。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "悠真失蹤。睡眠研究。筑波設施。G07／12。千田的 TKS 公開履歷。這些是這一次的普通證據。你今天就能查證。不需要相信我說的任何一句關於循環的話。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部靠回椅背。他看著天花板。看了十秒。然後低下頭。看著桌上那杯沒打開的礦泉水。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他的肩膀放下了一點。不是放鬆。是某種東西從繃緊變成了沉重。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯我不接受妳的解釋。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他停了一下。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "時間循環。世界倒流。這些——我沒辦法寫進報告。我沒辦法拿去申請搜查令。我沒辦法告訴上司「因為她說世界重來了」。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他又停了一下。手指在桌面上壓平。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "但我接受這不是巧合到可以放著不管。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯他說了。他不接受解釋。但他接受行動。個人的事——我知道了這一次不可能知道的事。他腦中也有一點不該存在的東西。職業的事——不能把循環寫進報告。只能依這一次的失蹤案、公開研究資料來行動。這就是界線。他不會說「我相信你」。但他會動。這就夠了。今天——這就夠了。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "07:12。便利店裡的冷櫃馬達換了一個頻率。窗外亮了一點。星期一正式開始了。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部站起來。把椅子推回桌下。", background: Background.Chapter_17_Ch17_Act2_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯走。上車。", background: Background.Chapter_17_Ch17_Act2_S0, portrait: Portrait.KusakubeSatoru_Base },
];
